import pandas as pd
from scipy.stats import linregress
import matplotlib.pyplot as plt
import numpy as np

# Generated by Claude then modified manually ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

# columns you want to keep
columns_to_keep = ["time", "dt", "altitude_barometric", "mass_total", "density", "air_temperature","air_brakes_extension","air_pressure"]

# intial conditions
columnNames = ["seaTemp","groundPressure","lapserate","initialVelocity","initialAltitude","apogee","initialPitch"]
initialConditions = pd.DataFrame(columns = columnNames)

for i in range(0, 201):
    frame = pd.read_csv(f"saturnSims/Without_Airbrakes/SATURN_dataframe_{i}.csv")

    groundPressure = frame["air_pressure"][0]
    
    # keep only the columns that are in the list AND actually exist in this frame
    cols_present = [col for col in columns_to_keep if col in frame.columns]
    chopped = frame[cols_present]
    
    # --- find start cutoff: first point where mass_motor settles to a constant value ---
    mass_diff = frame["mass_motor"].diff()
    changed = mass_diff[mass_diff != 0]
    
    # the last row where mass_motor actually changed is where it "settles" from
    start_idx = changed.index[-1] if not changed.empty else chopped.index[0]

    # calculate the initial velcity using the centre difference
    initVel = (frame['altitude_barometric'][start_idx+1]-frame['altitude_barometric'][start_idx-1])/(2*frame['dt'][0])

    # get the initial altitude
    initAlt = frame['altitude_barometric'][start_idx]

    # get the initial pitch
    initPitch = frame['pitch'][start_idx]
    
    # --- find end cutoff: first point where altitude_barometric decreases ---
    alt_diff = chopped["altitude_barometric"].diff()
    decreased = alt_diff < 0
    end_idx = (decreased.idxmax() - 1) if decreased.any() else chopped.index[-1]

    # get apogee
    apogee = chopped["altitude_barometric"][end_idx]
    
    
    # apply both boundaries at once
    chopped = chopped.loc[start_idx:end_idx]

    # Perform linear regression on temperature and altitude to get sea level temperature and lapse rate
    regression = linregress(chopped["altitude_barometric"], chopped["air_temperature"])

    # calculate the lapse rate
    lapseRate = regression.slope
    seaTemp = regression.intercept

    # plot the temperature and altitude in order to validate regression.
    # should be commented out in final version of code
    """
    testAlts = np.arange(0,3500,100)

    plt.plot(chopped["altitude_barometric"],chopped["air_temperature"],label="True data")
    plt.plot(testAlts,seaTemp+lapseRate*testAlts,label="Regression")
    plt.show()
    """

    chopped.to_csv(f"saturnSims/Without_Airbrakes_Scrubbed/frame{i}_timeseries.csv", index=False)

    # ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; - Verified by comparing against doing the process for dataframe_0 manually, outputs match

    initialConditions.loc[i] = [seaTemp, groundPressure, lapseRate, initVel, initAlt, apogee, initPitch]

    print(f"progess: {(i/201)*100:.0f}%",end='\r')


initialConditions.to_csv(f"saturnSims/Without_Airbrakes_Scrubbed/all_initialconds.csv", index=False)

print("Program completed")